2857:ucl_parser_add_chunk_full (struct ucl_parser *parser, const unsigned char *data,
2986:   return ucl_parser_add_chunk_full (parser, data, len,
2998:   return ucl_parser_add_chunk_full (parser, data, len,
3021:   res = ucl_parser_add_chunk_full (parser, data, len, parser->chunks->priority,
                                        ucl_create_err (&parser->err,
                                                        "error at %s:%d at column %d: invalid macro",
                                                        chunk->fname ? chunk->fname : "memory",
                                                        chunk->line,
                                                        chunk->column);
                                        parser->state = UCL_STATE_ERROR;
                                        return false;
                                }
                                else {
                                        p = chunk->pos;
                                        parser->state = parser->prev_state;
                                }
                        }
                        else {
                                if (!ucl_test_character (*p, UCL_CHARACTER_WHITESPACE_UNSAFE) &&
                                                *p != '(') {
                                        ucl_chunk_skipc (chunk, p);
                                }
                                else {
                                        if (c != NULL && p - c > 0) {
                                                /* We got macro name */
                                                macro_len = (size_t) (p - c);
                                                HASH_FIND (hh, parser->macroes, c, macro_len, macro);
                                                if (macro == NULL) {
                                                        ucl_create_err (&parser->err,
                                                                        "error at %s:%d at column %d: "
                                                                        "unknown macro: '%.*s', character: '%c'",
                                                                        chunk->fname ? chunk->fname : "memory",
                                                                        chunk->line,
                                                                        chunk->column,
                                                                        (int) (p - c),
                                                                        c,
                                                                        *chunk->pos);
                                                        parser->state = UCL_STATE_ERROR;
                                                        return false;
                                                }
                                                /* Now we need to skip all spaces */
                                                SKIP_SPACES_COMMENTS(parser, chunk, p);
                                                parser->state = UCL_STATE_MACRO;
                                        }
                                        else {
                                                /* We have invalid macro name */
                                                ucl_create_err (&parser->err,
                                                                "error at %s:%d at column %d: invalid macro name",
                                                                chunk->fname ? chunk->fname : "memory",
                                                                chunk->line,
                                                                chunk->column);
                                                parser->state = UCL_STATE_ERROR;
                                                return false;
                                        }
                                }
                        }
                        break;
                case UCL_STATE_MACRO:
                        if (*chunk->pos == '(') {
                                macro_args = ucl_parse_macro_arguments (parser, chunk);
                                p = chunk->pos;
                                if (macro_args) {
                                        SKIP_SPACES_COMMENTS(parser, chunk, p);
                                }
                        }
                        else {
                                macro_args = NULL;
                        }
                        if (!ucl_parse_macro_value (parser, chunk, macro,
                                        &macro_start, &macro_len)) {
                                parser->prev_state = parser->state;
                                parser->state = UCL_STATE_ERROR;
                                return false;
                        }
                        macro_len = ucl_expand_variable (parser, &macro_escaped,
                                        macro_start, macro_len);
                        parser->state = parser->prev_state;

                        if (macro_escaped == NULL && macro != NULL) {
                                if (macro->is_context) {
                                        ret = macro->h.context_handler (macro_start, macro_len,
                                                        macro_args,
                                                        parser->top_obj,
                                                        macro->ud);
                                }
                                else {
                                        ret = macro->h.handler (macro_start, macro_len, macro_args,
                                                        macro->ud);
                                }
                        }
                        else if (macro != NULL) {
                                if (macro->is_context) {
                                        ret = macro->h.context_handler (macro_escaped, macro_len,
                                                        macro_args,
                                                        parser->top_obj,
                                                        macro->ud);
                                }
                                else {
                                        ret = macro->h.handler (macro_escaped, macro_len, macro_args,
                                                macro->ud);
                                }

                                UCL_FREE (macro_len + 1, macro_escaped);
                        }
                        else {
                                ret = false;
                                ucl_set_err (parser, UCL_EINTERNAL,
                                                "internal error: parser has macro undefined", &parser->err);
                        }

                        /*
                         * Chunk can be modified within macro handler
                         */
                        chunk = parser->chunks;
                        p = chunk->pos;

                        if (macro_args) {
                                ucl_object_unref (macro_args);
                        }

                        if (!ret) {
                                return false;
                        }
                        break;
                default:
                        ucl_set_err (parser, UCL_EINTERNAL,
                                        "internal error: parser is in an unknown state", &parser->err);
                        parser->state = UCL_STATE_ERROR;
                        return false;
                }
